<?php require __DIR__.'/includes/bootstrap.php';$exists=(int)$pdo->query('SELECT COUNT(*) FROM admins')->fetchColumn();if($exists){exit('An administrator already exists. Delete setup-admin.php now.');}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$name=trim($_POST['name']??'');$email=filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL);$pass=$_POST['password']??'';if(!$name||!$email||strlen($pass)<12)$error='Enter a name, valid email and password of at least 12 characters.';else{$q=$pdo->prepare('INSERT INTO admins(name,email,password_hash) VALUES(?,?,?)');$q->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);echo 'Administrator created. Delete setup-admin.php immediately, then log in at admin/login.php.';exit;}}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Create first administrator</title><link rel="stylesheet" href="admin/style.css"></head><body><div class="wrap" style="max-width:520px"><div class="panel"><h1>Create first administrator</h1><p>Run this once after importing database.sql and configuring config.php.</p><?php if($error):?><p><?=e($error)?></p><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Full name</label><input name="name" required><label>Email</label><input type="email" name="email" required><label>Password (minimum 12 characters)</label><input type="password" name="password" minlength="12" required><button class="btn">Create administrator</button></form></div></div></body></html>